"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useTheme } from "./ThemeProvider";

interface LogoProps {
  variant?: "full" | "icon" | "wordmark";
  theme?: "light" | "dark";
  size?: "sm" | "md" | "lg";
  showTagline?: boolean;
  className?: string;
  href?: string;
  onClick?: (e: React.MouseEvent) => void;
}

// Normalized 1:1 square canvas transparent logo icons (Strictly identical 512x512 size and centering)
const LIGHT_ICON_DATA_URI = "data:image/png;base64,";
const DARK_ICON_DATA_URI = "data:image/png;base64,";

export default function Logo({
  variant = "full",
  theme,
  size = "md",
  showTagline = false,
  className = "",
  href,
  onClick,
}: LogoProps) {
  const pathname = usePathname();
  const themeContext = useTheme();
  
  // Use explicit theme prop if passed, otherwise fall back to themeContext
  const isDark = theme ? theme === "dark" : themeContext?.theme === "dark";

  const sizeClasses = {
    sm: { icon: "h-8 w-8", text: "text-lg", tagline: "text-[9px]" },
    md: { icon: "h-10 w-10", text: "text-xl", tagline: "text-[11px]" },
    lg: { icon: "h-12 w-12", text: "text-3xl", tagline: "text-xs" },
  }[size];

  const iconSrc = isDark ? DARK_ICON_DATA_URI : LIGHT_ICON_DATA_URI;

  const handleClick = (e: React.MouseEvent) => {
    if (onClick) {
      onClick(e);
    }
    // If clicking on logo when already on the href page (e.g. '/' on landing page or dashboard), scroll to top smoothly
    if (href && (pathname === href || (href === "/" && (pathname === "/" || pathname === "/landing")))) {
      e.preventDefault();
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  const content = (
    <div className={`inline-flex items-center gap-2.5 ${className}`}>
      {/* Official PersonaMail Logo Icon (Normalized 1:1 Square Canvas, Zero Shift) */}
      {(variant === "full" || variant === "icon") && (
        <div className={`relative shrink-0 flex items-center justify-center ${sizeClasses.icon}`}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={iconSrc}
            alt="PersonaMail Logo Icon"
            className="h-full w-full object-contain"
          />
        </div>
      )}

      {/* PersonaMail Wordmark */}
      {(variant === "full" || variant === "wordmark") && (
        <div className="flex flex-col">
          <span
            className={`font-bold tracking-tight ${sizeClasses.text} ${
              isDark ? "text-white" : "text-slate-900 dark:text-white"
            }`}
          >
            Persona<span className="text-[#38BDF8] dark:text-[#7CE3FF]">Mail</span>
          </span>
          {showTagline && (
            <span
              className={`font-semibold tracking-wider uppercase ${sizeClasses.tagline} ${
                isDark ? "text-slate-400" : "text-slate-500 dark:text-slate-400"
              }`}
            >
              Every conversation remembers who it’s for.
            </span>
          )}
        </div>
      )}
    </div>
  );

  if (href) {
    return (
      <Link
        href={href}
        onClick={handleClick}
        className="inline-flex rounded-lg focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[#7CE3FF]"
      >
        {content}
      </Link>
    );
  }

  return (
    <div onClick={handleClick} className="cursor-pointer">
      {content}
    </div>
  );
}
